package apicompat
import("strings";"testing")
func BenchmarkOpenThinkingFragments(b *testing.B){fragment:=strings.Repeat("x",1024);b.ReportAllocs();b.SetBytes(1<<20);for i:=0;i<b.N;i++{s:=NewAnthropicEventToResponsesState();AnthropicEventToResponsesEvents(&AnthropicStreamEvent{Type:"message_start",Message:&AnthropicResponse{Model:"claude-opus-5-5"}},s);AnthropicEventToResponsesEvents(&AnthropicStreamEvent{Type:"content_block_start",ContentBlock:&AnthropicContentBlock{Type:"thinking"}},s);for j:=0;j<1024;j++{AnthropicEventToResponsesEvents(&AnthropicStreamEvent{Type:"content_block_delta",Delta:&AnthropicDelta{Type:"thinking_delta",Thinking:fragment}},s)};AnthropicEventToResponsesEvents(&AnthropicStreamEvent{Type:"content_block_delta",Delta:&AnthropicDelta{Type:"signature_delta",Signature:"sig"}},s);AnthropicEventToResponsesEvents(&AnthropicStreamEvent{Type:"content_block_stop"},s)}}
